/* ---------------- Firebase bootstrap ---------------- */
var fdb=null, fauth=null, uid=null, fbReady=false, fbError=null;
function initFirebase(){
  return new Promise(function(resolve){
    try{
      if(!window.firebase || firebaseConfig.apiKey.indexOf("__")===0){ fbError="noconfig"; return resolve(); }
      firebase.initializeApp(firebaseConfig);
      fdb=firebase.firestore(); fauth=firebase.auth();
      fauth.signInAnonymously().catch(function(e){ fbError=e.code||"auth"; });
      fauth.onAuthStateChanged(function(u){ if(u){uid=u.uid;} fbReady=true; resolve(); });
      setTimeout(function(){ if(!fbReady){ fbReady=true; resolve(); } }, 7000);
    }catch(e){ fbError=e.message||"init"; resolve(); }
  });
}

