function el(id){return document.getElementById(id);}
function esc(s){return String(s==null?'':s).replace(/[&<>"]/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]);});}
function makeCode(){var a='ABCDEFGHJKMNPQRSTUVWXYZ23456789',s='';for(var i=0;i<5;i++)s+=a[Math.floor(Math.random()*a.length)];return s;}
function makeId(){return 's_'+Date.now().toString(36)+Math.random().toString(36).slice(2,7);}

/* PATH: pre-test score only (no NGRT). ready <=4/10, go >=8/10, else steady.
   A very low score (<=3) also flags the student for a teacher check-in. */
function placeByScore(score,total){
  var pct=total?score/total:0;
  if(pct>=0.8) return 'go';
  if(pct<=0.4) return 'ready';
  return 'steady';
}


/* ===================== FIRESTORE ===================== */
function studentRef(){ return fdb.collection('sessions').doc(S.code).collection('students').doc(S.studentId); }
function saveStudent(extra){
  if(!fdb||!S.code||!S.studentId) return Promise.resolve();
  var doc={name:S.name,tier:S.tier,preScore:S.preScore,preTotal:S.preTotal,lowTestFlag:!!S.lowTestFlag,
    stage:STAGES[S.stageIndex],stageIndex:S.stageIndex,usedGo:!!S.usedGo,placed:!!S.placed,badge:!!S.badge,
    percent:progressPct(),updated:Date.now(),
    // full state for resume + teacher analytics
    answers:S.answers||{}, picks:S.picks||{}, scores:S.stageScores||{}};
  if(extra) for(var k in extra) doc[k]=extra[k];
  try{ return studentRef().set(doc,{merge:true}).catch(function(){}); }catch(e){ return Promise.resolve(); }
}
function ensureSession(code){
  if(!fdb) return Promise.resolve();
  try{ return fdb.collection('sessions').doc(code).set({code:code,title:'Food Preservation',created:Date.now()},{merge:true}).catch(function(){}); }
  catch(e){ return Promise.resolve(); }
}
function sessionExists(code){
  if(!fdb) return Promise.resolve(null);
  return fdb.collection('sessions').doc(code).get().then(function(d){
    if(d.exists) return true;
    return fdb.collection('sessions').doc(code).collection('students').limit(1).get().then(function(s){return !s.empty;});
  }).catch(function(){return null;});
}
/* Teacher writes pacing on the session doc; students read it live. */
function setPacing(code, fields){
  if(!fdb) return Promise.resolve();
  try{ return fdb.collection('sessions').doc(code).set(fields,{merge:true}).catch(function(){}); }catch(e){ return Promise.resolve(); }
}
/* Student subscribes to session meta (paced + releasedIndex). Auto-advances past the wait screen on release. */
function subscribeMeta(code){
  if(!fdb||!code) return;
  if(S.metaUnsub){try{S.metaUnsub();}catch(e){}S.metaUnsub=null;}
  try{
    S.metaUnsub=fdb.collection('sessions').doc(code).onSnapshot(function(d){
      var m=d.exists?(d.data()||{}):{};
      S.paced = !!m.paced;
      S.releasedIndex = (typeof m.releasedIndex==='number') ? m.releasedIndex : (STAGES.length-1);
      // If the student is on the wait screen and the gate has opened, move them on.
      if(S.waiting && (!S.paced || S.stageIndex <= S.releasedIndex)){
        S.waiting=false; render();
      }
    });
  }catch(e){}
}
/* can the student move to the given target stage index right now? */
function gateAllows(targetIndex){ return !S.paced || targetIndex <= S.releasedIndex; }

/* ===================== ROUTER ===================== */
function go(v){location.hash=v;render();}
window.addEventListener('hashchange',render);
function render(){
  var h=(location.hash||'').replace('#','');
  var sc=el('screen');
  if(h!=='classview') document.body.classList.remove('projector');
  if(h==='teacher') return renderTeacher(sc);
  if(h==='dashboard') return renderDashboard(sc);
  if(h==='classview') return renderClassView(sc);
  if(h==='student') return renderStudentFlow(sc);
  return renderLanding(sc);
}

