/* ---------------- STUDENT ---------------- */
function renderStudentFlow(sc){ if(!S.studentId) return renderJoin(sc); return renderStage(sc); }
function renderJoin(sc){
  sc.innerHTML=
  '<div class="slide"><div class="slide-head"><span class="gem">&#129516;</span><h2>Join your class</h2></div>'+
  '<div class="slide-body"><label class="fld" for="jCode">Class code from your teacher</label>'+
    '<input class="in code-in" id="jCode" maxlength="5" placeholder="ABCDE" style="max-width:260px">'+
    '<label class="fld" for="jName">Your name</label>'+
    '<input class="in" id="jName" placeholder="e.g. Amina K." maxlength="40" style="max-width:360px">'+
    '<div class="fb no" id="jFb"></div>'+
    '<div class="btn-row"><button class="btn" id="joinBtn">Start &#8594;</button><button class="btn ghost" onclick="go(\'\')">&#8592; Back</button></div>'+
    '<img class="crest" src="'+LOGO+'" alt=""></div></div>';
  el('joinBtn').addEventListener('click',function(){
    var code=(el('jCode').value||'').trim().toUpperCase(),name=(el('jName').value||'').trim(),btn=this,f=el('jFb');
    if(code.length!==5){f.className='fb show no';f.textContent='Ask your teacher for the 5-letter code.';return;}
    if(!name){f.className='fb show no';f.textContent='Please type your name.';return;}
    btn.disabled=true;btn.textContent='Joining…';
    sessionExists(code).then(function(ex){
      if(fdb&&ex===false){f.className='fb show no';f.textContent='That code isn’t open. Check it with your teacher.';btn.disabled=false;btn.textContent='Start →';return;}
      S.code=code;S.name=name;ensureSession(code);subscribeMeta(code);
      // RESUME: if a student with this name already exists in the class, pick up where they left off.
      findStudentByName(code,name).then(function(existing){
        if(existing){
          S.studentId=existing.id; restoreFromDoc(existing.data);
          f.className='fb show ok'; f.innerHTML='<b>Welcome back, '+esc(name)+'!</b> Continuing where you left off.';
          saveStudent(); setTimeout(render,500);
        } else {
          S.studentId=makeId();S.stageIndex=0;S.answers={};S.picks={};S.stageScores={};saveStudent();render();
        }
      });
    });
  });
}
/* Find an existing student doc in this class with a matching (case-insensitive) name. */
function findStudentByName(code,name){
  if(!fdb) return Promise.resolve(null);
  var want=name.trim().toLowerCase();
  return fdb.collection('sessions').doc(code).collection('students').get().then(function(snap){
    var hit=null;
    snap.forEach(function(d){ var v=d.data()||{}; if(!hit && (v.name||'').trim().toLowerCase()===want) hit={id:d.id,data:v}; });
    return hit;
  }).catch(function(){return null;});
}
/* Restore saved progress into S. */
function restoreFromDoc(v){
  v=v||{};
  S.stageIndex = typeof v.stageIndex==='number'?v.stageIndex:0;
  S.tier = v.tier||'steady';
  S.preScore = (v.preScore!=null)?v.preScore:null;
  S.preTotal = v.preTotal||0;
  S.lowTestFlag = !!v.lowTestFlag;
  S.placed = !!v.placed;
  S.usedGo = !!v.usedGo;
  S.badge = !!v.badge;
  S.answers = v.answers||{};
  S.picks = v.picks||{};
  S.stageScores = v.scores||{};
}

function stepBar(){
  var html='<div class="steps">';
  for(var i=0;i<STAGES.length;i++){var cl=i<S.stageIndex?'done':(i===S.stageIndex?'now':'');html+='<span class="step-dot '+cl+'">'+(i<S.stageIndex?'✓ ':'')+esc(STAGE_LABEL[STAGES[i]])+'</span>';}
  html+='</div><div class="prog"><div class="bar"><div class="fill" style="width:'+progressPct()+'%"></div></div><div class="pct tnum">'+progressPct()+'%</div></div>';
  return html;
}
function progressPct(){return Math.round((S.stageIndex/(STAGES.length-1))*100);}

function renderStage(sc){
  var stage=STAGES[S.stageIndex];
  var top='<div style="display:flex;align-items:center;gap:10px;margin-bottom:8px;flex-wrap:wrap">'+
    '<span class="chip '+S.tier+'">'+esc(TIER_LABEL[S.tier])+' path</span>'+
    (S.lowTestFlag?'<span class="flag warn">teacher: check me</span>':'')+
    '<span style="color:var(--ink-soft);font-size:.85rem">'+esc(S.name)+'</span>'+
    '<button class="tier-switch" onclick="openTierPicker()">change path</button></div>'+stepBar();
  if(S.waiting && !gateAllows(Math.min(S.stageIndex+1,STAGES.length-1))){
    sc.innerHTML=top+stageWait(); return;
  }
  var body=({pretest:stagePretest,recap:stageRecap,spoilage:stageSpoilage,outcome1:stageOutcome1,cfu:stageCFU,
    outcome2:stageOutcome2,hook:stageHook,stations:stageStations,common:stageCommon,explain:stageExplain,done:stageDone,casestudy:stageCaseStudy}[stage])();
  sc.innerHTML=top+body;
  restoreInputs();          // put back anything the student already typed/selected
  wireStage(stage);
  captureInputs();          // keep S.answers live as they type
}
/* Save every text box / checkbox value into S.answers as the student types. */
function captureInputs(){
  document.querySelectorAll('#screen textarea[id], #screen input[id]').forEach(function(elm){
    if(elm.type==='checkbox'){
      elm.addEventListener('change',function(){ S.answers[elm.id]=elm.checked; });
    } else if(elm.type!=='button'){
      var h=function(){ S.answers[elm.id]=elm.value; };
      elm.addEventListener('input',h); elm.addEventListener('change',h);
    }
  });
}
/* Restore text boxes, checkboxes, and selected MCQ/multi options after a re-render. */
function restoreInputs(){
  document.querySelectorAll('#screen textarea[id], #screen input[id]').forEach(function(elm){
    if(!(elm.id in S.answers)) return;
    if(elm.type==='checkbox'){
      elm.checked=!!S.answers[elm.id];
      var lab=elm.closest('.nbtask'); if(lab) lab.classList.toggle('checked',elm.checked);
    } else {
      elm.value=S.answers[elm.id];
    }
  });
  // re-apply chosen options (qi may be a real question index, or '0' for standalone choices with no data-qi)
  for(var cls in S.picks){
    var byQ=S.picks[cls];
    for(var qi in byQ){
      byQ[qi].forEach(function(oi){
        var b=document.querySelector('.'+cls+'[data-qi="'+qi+'"][data-oi="'+oi+'"]');
        if(!b) b=document.querySelector('.'+cls+':not([data-qi])[data-oi="'+oi+'"]');
        if(b){ b.classList.add('sel'); var k=b.querySelector('.k'); if(k&&b.classList.contains('multi')) k.innerHTML='&#9745;'; }
      });
    }
  }
}
function recordPick(cls,qi,oi,multi){
  S.picks[cls]=S.picks[cls]||{};
  if(multi){
    var arr=S.picks[cls][qi]||[]; var i=arr.indexOf(oi);
    if(i>=0) arr.splice(i,1); else arr.push(oi);
    S.picks[cls][qi]=arr;
  } else {
    S.picks[cls][qi]=[oi];
  }
}
function stageWait(){
  var nextName=STAGE_LABEL[STAGES[Math.min(S.stageIndex+1,STAGES.length-1)]];
  return '<div class="slide"><div class="slide-head teal"><span class="gem">&#10073;&#10073;</span><h2>Pause here</h2></div>'+
  '<div class="slide-body" style="text-align:center;padding-bottom:40px">'+
    '<div style="font-size:2.6rem;margin:8px 0">&#9201;&#65039;</div>'+
    '<p class="inquiry" style="margin:0 auto 6px;max-width:30ch">Well done, '+esc(S.name)+' — you’ve finished this part.</p>'+
    '<p class="muted">Waiting for your teacher to release <b>'+esc(nextName)+'</b>. This continues on its own — keep your eyes up front. &#9733;</p>'+
    '<div class="wait-dots"><span></span><span></span><span></span></div>'+
    '<img class="crest" src="'+LOGO+'" alt=""></div></div>';
}

/* ---- tier picker overlay. advanceAfter=true (after the pre-test) moves the student
   INTO the lesson on confirm; false (the "change path" button mid-lesson) just re-renders
   the current stage with the new tier applied. ---- */
function openTierPicker(advanceAfter){
  var rec=S.tier;
  var cards=TIERS.map(function(t){
    return '<button type="button" class="tier-card '+t+(t===rec?' rec':'')+'" data-tier="'+t+'">'+
      '<div class="tier-name">'+esc(TIER_LABEL[t])+(t===rec?' <span class="tier-badge">recommended</span>':'')+'</div>'+
      '<div class="tier-blurb">'+esc(TIER_BLURB[t])+'</div></button>';
  }).join('');
  var scoreLine = (advanceAfter && S.preScore!=null)
    ? '<div class="score-box"><div class="score-num">'+S.preScore+' / '+S.preTotal+'</div><div class="score-lab">your pre-test score</div></div>'
    : '';
  var ov=document.createElement('div');ov.className='tier-overlay';ov.id='tierOverlay';
  ov.innerHTML='<div class="tier-panel"><h3>'+(advanceAfter?'Your result':'Choose your path')+'</h3>'+
    scoreLine+
    '<p class="muted" style="margin:2px 0 12px">Your pre-test suggests <b>'+esc(TIER_LABEL[rec])+'</b>. You can pick any path — move up whenever you’re ready.</p>'+
    '<div class="tier-cards">'+cards+'</div>'+
    '<div class="btn-row"><span class="sp"></span><button class="btn" id="tierDone">'+(advanceAfter?'Start the lesson →':'Use this path')+'</button></div></div>';
  document.body.appendChild(ov);
  var sel=rec;
  ov.querySelectorAll('.tier-card').forEach(function(b){b.addEventListener('click',function(){ov.querySelectorAll('.tier-card').forEach(function(x){x.classList.remove('sel');});b.classList.add('sel');sel=b.getAttribute('data-tier');});});
  (ov.querySelector('.tier-card.'+rec)||{}).classList&&ov.querySelector('.tier-card.'+rec).classList.add('sel');
  el('tierDone').addEventListener('click',function(){
    S.tier=sel;S.usedGo=(sel==='go')||S.usedGo;saveStudent();
    if(ov.parentNode) document.body.removeChild(ov);
    if(advanceAfter){ advance(); } else { render(); }
  });
}

/* ---- lock the pre-test after one attempt (no changing answers) ---- */
function lockPretest(){
  document.querySelectorAll('.pre-opt').forEach(function(b){ b.disabled=true; b.style.pointerEvents='none'; b.classList.add('locked'); });
  var pc=el('preCheck'); if(pc){ pc.disabled=true; pc.style.display='none'; }
}
/* ---- re-mark correct/incorrect and show the score (used on submit and on re-render) ---- */
function showPreResult(){
  // mark green/red against the stored answers
  PRETEST.forEach(function(it,qi){
    var ans=answerSet(it);
    document.querySelectorAll('.pre-opt[data-qi="'+qi+'"]').forEach(function(b){
      var oi=parseInt(b.getAttribute('data-oi'),10);
      var inAns=ans.indexOf(oi)>=0, picked=b.classList.contains('sel');
      b.classList.remove('correct','wrong');
      if(inAns) b.classList.add('correct');
      else if(picked) b.classList.add('wrong');
    });
  });
  var f=el('preFb');
  if(f){ f.className='fb show ok'; f.innerHTML='<b>Your score: '+S.preScore+' / '+S.preTotal+'.</b> Correct answers are shown in green. This is your one attempt — answers are now locked.'; }
}

