/* ===================== WIRING ===================== */
function clsOf(btn){ return ['pre-opt','rec-opt','cfu-opt','pc-opt','pcm-opt','tech-opt','cs-opt'].filter(function(c){return btn.classList.contains(c);})[0]||''; }
/* show a thumbnail when a photo is chosen (kept in-memory only; not uploaded anywhere) */
function wirePhoto(inputId,prevId){
  var inp=el(inputId), prev=el(prevId); if(!inp||!prev) return;
  inp.addEventListener('change',function(){
    var fl=inp.files&&inp.files[0]; if(!fl) return;
    var url=URL.createObjectURL(fl);
    prev.innerHTML='<img src="'+url+'" alt="your photo"><span class="photo-ok">✓ photo added</span>';
  });
}
function selWire(){
  document.querySelectorAll('.choice').forEach(function(btn){
    if(btn.disabled||btn.classList.contains('locked')) return;
    btn.addEventListener('click',function(){
      var cls=clsOf(btn);
      var qi=btn.getAttribute('data-qi'); var qkey=(qi!=null?qi:'0');
      var oi=parseInt(btn.getAttribute('data-oi'),10);
      var q=btn.closest('.qblock');
      var multi = q && q.getAttribute('data-multi')==='1';
      if(multi){
        btn.classList.toggle('sel'); var k=btn.querySelector('.k'); if(k) k.innerHTML=btn.classList.contains('sel')?'&#9745;':'&#9744;';
        recordPick(cls,qkey,oi,true); return;
      }
      // single-select: clear siblings in the same question (or same class group for standalone choices)
      var scope=(qi!=null)?('.'+cls+'[data-qi="'+qi+'"]'):('.'+cls);
      document.querySelectorAll(scope).forEach(function(b){b.classList.remove('sel');});
      btn.classList.add('sel');
      recordPick(cls,qkey,oi,false);
    });
  });
}
function wireStage(stage){
  selWire();
  var adv=function(){advance();};

  if(stage==='pretest'){
    // If the student already submitted (re-render / came back), show the locked result — one attempt only.
    if(S.preScore!=null && S.placed){ lockPretest(); showPreResult(); }
    el('preCheck').addEventListener('click',function(){
      if(S.preScore!=null){ return; } // already attempted — no second try
      var f=el('preFb');
      // every question must have at least one selection
      var unanswered=[];
      PRETEST.forEach(function(it,qi){ if(!document.querySelector('.pre-opt[data-qi="'+qi+'"].sel')) unanswered.push(qi+1); });
      if(unanswered.length){ f.className='fb show no'; f.textContent='Please answer every question first (missing: '+unanswered.join(', ')+').'; return; }
      var r=gradeQuiz(PRETEST,'pre-opt');
      S.preScore=r.score; S.preTotal=r.max;
      S.lowTestFlag = r.score<=3;
      S.tier=placeByScore(r.score,r.max);
      S.placed=true;
      lockPretest();           // one attempt: freeze the answers
      showPreResult();         // show the score inline
      saveStudent();
      openTierPicker(true);    // pick a path, then advance INTO the lesson
    });
    el('preNext').addEventListener('click',adv);
  }

  if(stage==='recap'){
    el('recCheck').addEventListener('click',function(){
      var r=gradeQuiz(RECAP.items,'rec-opt'),f=el('recFb');
      if(r.answered<RECAP.items.length){f.className='fb show no';f.textContent='Answer all four, then check.';return;}
      f.className='fb show ok';f.innerHTML='<b>'+r.score+' / '+r.max+'.</b> Spoilage is a chemical change; preservation slows it down.';
      el('recNextRow').style.display='flex'; saveStudent();
    });
    el('recNext').addEventListener('click',adv);
  }

  if(stage==='spoilage'){ el('spNext').addEventListener('click',adv); }
  if(stage==='outcome1'){ el('o1Next').addEventListener('click',adv); }
  if(stage==='outcome2'){ el('o2Next').addEventListener('click',adv); }
  if(stage==='hook'){ wireNotebookTask('hk'); el('hkNext').addEventListener('click',function(){saveStudent({hookDone:!!(el('hkDone')&&el('hkDone').checked)});advance();}); }

  if(stage==='cfu'){
    el('cfuCheck').addEventListener('click',function(){
      var sel=document.querySelector('.cfu-opt.sel'),f=el('cfuFb');
      if(!sel){f.className='fb show no';f.textContent='Pick an answer first.';return;}
      document.querySelectorAll('.cfu-opt').forEach(function(b){var oi=parseInt(b.getAttribute('data-oi'),10);if(oi===CFU.answer)b.classList.add('correct');else if(b.classList.contains('sel'))b.classList.add('wrong');});
      var ok=parseInt(sel.getAttribute('data-oi'),10)===CFU.answer;
      S.stageScores.cfu=ok?1:0;
      f.className='fb show ok';f.innerHTML='<b>'+(ok?'Correct!':'Good try.')+'</b> '+CFU.feedback;
      el('cfuNextRow').style.display='flex'; saveStudent();
    });
    el('cfuNext').addEventListener('click',adv);
  }

  if(stage==='stations'){
    // photo previews + notebook ticks for each station
    STATIONS.stations.forEach(function(st){
      wirePhoto('st'+st.n+'photo','st'+st.n+'prev');
      wireNotebookTask('st'+st.n);
    });
    // progress check (folded in): Check reveals the Next button
    el('pcCheck').addEventListener('click',function(){
      var sel=document.querySelector('.pc-opt.sel'),f=el('pcFb');
      var rm=gradeQuiz([PROGRESS.match],'pcm-opt');
      if(!sel||rm.answered<1){f.className='fb show no';f.textContent='Answer the question and the match-all, then check.';return;}
      document.querySelectorAll('.pc-opt').forEach(function(b){var oi=parseInt(b.getAttribute('data-oi'),10);if(oi===PROGRESS.mcq.answer)b.classList.add('correct');else if(b.classList.contains('sel'))b.classList.add('wrong');});
      var ok=parseInt(sel.getAttribute('data-oi'),10)===PROGRESS.mcq.answer;
      S.stageScores.progress=(ok?1:0)+' + '+rm.score+'/'+rm.max;
      f.className='fb show ok';f.innerHTML='<b>'+(ok?'Correct!':'Look again.')+'</b> Drying removes moisture, which limits microbial growth.';
      el('stNextRow').style.display='flex'; saveStudent();
    });
    el('stNext').addEventListener('click',function(){
      var picks={}; STATIONS.stations.forEach(function(st){
        var b=document.querySelector('.tech-opt[data-qi="'+st.n+'"].sel');
        picks['s'+st.n]={tech:b?parseInt(b.getAttribute('data-oi'),10):null, done:!!(el('st'+st.n+'Done')&&el('st'+st.n+'Done').checked)};
      });
      saveStudent({stations:picks}); advance();
    });
  }

  if(stage==='common'){ el('cmNext').addEventListener('click',function(){saveStudent({common:{a1:val('cmWrite1'),a2:val('cmWrite2')}});advance();}); }

  if(stage==='done'){
    if(el('printCert')) el('printCert').addEventListener('click',printCertificate);
    if(el('toCase')) el('toCase').addEventListener('click',adv);
  }

  if(stage==='casestudy'){
    STATIONS; // no-op
    ['csChart','csQ1','csQ2','csQ3'].forEach(function(id){ wireNotebookTask(id); });
    el('csCheck').addEventListener('click',function(){
      var sel=document.querySelector('.cs-opt.sel'),f=el('csFb');
      if(!sel){f.className='fb show no';f.textContent='Pick an answer first.';return;}
      document.querySelectorAll('.cs-opt').forEach(function(b){var oi=parseInt(b.getAttribute('data-oi'),10);if(oi===CASE.check.answer)b.classList.add('correct');else if(b.classList.contains('sel'))b.classList.add('wrong');});
      var ok=parseInt(sel.getAttribute('data-oi'),10)===CASE.check.answer;
      S.stageScores.casestudy=ok?1:0;
      f.className='fb show ok';f.innerHTML='<b>'+(ok?'Correct!':'Good try.')+'</b> '+CASE.check.feedback;
      el('csNextRow').style.display='flex'; saveStudent();
    });
    el('csFinish').addEventListener('click',function(){
      S.stageScores.caseDone=true; saveStudent();
      el('screen').innerHTML='<div class="slide"><div class="slide-head teal"><span class="gem">&#9733;</span><h2>All done!</h2></div>'+
        '<div class="slide-body" style="text-align:center;padding-bottom:36px"><div style="font-size:2.6rem">&#127881;</div>'+
        '<p class="inquiry" style="margin:4px auto 6px;max-width:34ch">Fantastic work, '+esc(S.name)+' — you’ve completed the lesson and the water‑activity case study.</p>'+
        '<p class="muted">You can reprint your certificate or head back to the start.</p>'+
        '<div class="btn-row" style="justify-content:center"><button class="btn" onclick="S.stageIndex=STAGES.indexOf(\'done\');render();">◀ Back to certificate</button><button class="btn ghost" onclick="restartStudent()">Back to start</button></div>'+
        '<img class="crest" src="'+LOGO+'" alt=""></div></div>';
      window.scrollTo({top:0,behavior:'smooth'});
    });
  }

  if(stage==='explain'){
    if(el('pushStart')) el('pushStart').addEventListener('click',openPushQuiz);
    el('exNext').addEventListener('click',function(){
      if(showGo()&&val('e_extra').length>3)S.usedGo=true;
      saveStudent({explain:{food:val('e_food'),method:val('e_method'),cond:val('e_cond'),why:val('e_why'),extra:val('e_extra')}});
      advance();
    });
  }
}
function val(id){var e=el(id);return e?(e.value||'').trim():'';}
function advance(){
  var target=Math.min(S.stageIndex+1,STAGES.length-1);
  if(!gateAllows(target)){ S.waiting=true; saveStudent(); window.scrollTo({top:0,behavior:'smooth'}); render(); return; }
  S.stageIndex=target; S.waiting=false; saveStudent(); window.scrollTo({top:0,behavior:'smooth'}); render();
}


/* ---------------- boot ---------------- */
(function(){var bl=el('brandLogo');if(bl)bl.src=LOGO;})();
initFirebase().then(function(){ render(); });
